const toStr = (value) => {
  if (value === null || value === undefined) return null;
  const normalized = String(value).trim();
  return normalized ? normalized : null;
};

const dialogId = toStr(msg.req?.params?.dialogId);
if (!dialogId) {
  msg.statusCode = 400;
  msg.headers = { "Content-Type": "application/json; charset=utf-8" };
  msg.payload = { error: "dialogId is required" };
  return [null, msg, msg];
}

const q = msg.req?.query || {};
const limitRaw = Number(q.limit);
const limit = Number.isFinite(limitRaw) ? Math.max(1, Math.min(500, Math.floor(limitRaw))) : 100;
const beforeRaw = Number(q.beforeTs || q.before);
const beforeTs = Number.isFinite(beforeRaw) ? beforeRaw : Date.now() + 1;

msg._supportDialogMessages = { dialogId, limit, beforeTs };
msg.payload = {
  dialogId,
  deleted: { $ne: true },
  $or: [
    { createdTs: { $lt: beforeTs } },
    { createdTs: { $exists: false } },
    { createdTs: null },
  ],
};
return [msg, null, msg];

const toArray = (value) => (Array.isArray(value) ? value : []);
const toTs = (value) => {
  if (value === null || value === undefined || value === "") return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.trunc(parsed) : null;
};
const parseIsoTs = (value) => {
  if (value === null || value === undefined) return null;
  const parsed = Date.parse(String(value));
  return Number.isFinite(parsed) ? parsed : null;
};
const resolveCreatedTs = (row) => {
  const direct =
    toTs(row?.createdTs)
    ?? toTs(row?.timestamp)
    ?? parseIsoTs(row?.createdAt);
  return Number.isFinite(direct) ? direct : 0;
};

const ctx = msg._supportDialogMessages || { dialogId: null, limit: 100, beforeTs: Date.now() + 1 };
const rows = toArray(msg.payload)
  .filter((item) => item && typeof item === "object")
  .map((item) => {
    const createdTs = resolveCreatedTs(item);
    if (toTs(item.createdTs) !== null) return item;
    return Object.assign({}, item, {
      createdTs,
    });
  })
  .filter((item) => resolveCreatedTs(item) < Number(ctx.beforeTs || Date.now() + 1))
  .sort((left, right) => resolveCreatedTs(left) - resolveCreatedTs(right));

const sliced = rows.slice(Math.max(0, rows.length - ctx.limit));
const hasMore = rows.length > sliced.length;
const nextBeforeTs = sliced.length > 0 ? resolveCreatedTs(sliced[0]) : null;

msg.statusCode = 200;
msg.headers = { "Content-Type": "application/json; charset=utf-8" };
msg.payload = {
  dialogId: ctx.dialogId,
  totalFetched: sliced.length,
  hasMore,
  nextBeforeTs,
  messages: sliced,
};
return [msg, msg];
